using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;
// Explicit test process only. Contacts use the real touch router; fixture entities are labeled.
public static class DSPTouchRegression {
 [Serializable]public sealed class Check {public string name,evidence;public bool passed;}
 [Serializable]public sealed class Report {public string batchIdentifier,buildVersion,phase;public bool completed;public string source="PROGRAMMATIC touch contact router and raycast-checked HUD callbacks; physical finger ergonomics NOT verified";public List<Check> checks=new List<Check>();public List<string> errors=new List<string>();}
 static Report report;public static bool Passed {get;private set;}static Vector2 point;
 static void Write(){File.WriteAllText(Path.Combine(Application.persistentDataPath,"touch-regression.json"),JsonUtility.ToJson(report,true));}
 static void Note(string n,bool ok,string e){report.checks.Add(new Check{name=n,passed=ok,evidence=e});Write();}
 static void CheckTrue(bool c,string message){if(!c)throw new Exception(message);}
 static IEnumerator Wait(float s=.25f){yield return new WaitForSecondsRealtime(s);}
 static IEnumerator Button(string id){CheckTrue(DSPTouchControls.ClickDiagnostic(id),"HUD raycast or callback unavailable: "+id);yield return Wait(.35f);}
 static int Count(int proto){var f=GameMain.localPlanet.factory;int n=0;for(int i=1;i<f.entityCursor;i++)if(f.entityPool[i].id==i&&f.entityPool[i].protoId==proto)n++;for(int i=1;i<f.prebuildCursor;i++)if(f.prebuildPool[i].id==i&&f.prebuildPool[i].protoId==proto)n++;return n;}
 static IEnumerator Select(int proto){var p=GameMain.mainPlayer;p.TryAddItemToPackage(proto,100,0,false);int slot=-1;for(int i=0;i<p.package.size;i++)if(p.package.grids[i].itemId==proto){slot=i;break;}CheckTrue(slot>=0,"fixture stock missing");p.SetHandItems(proto,1,slot);yield return Wait(.45f);CheckTrue(DSPTouchControls.BuildActive,"original build tool not active");}
 static IEnumerator FindClick(){bool found=false;var a=GameMain.mainPlayer.controller.actionBuild;for(int y=5;y<=8&&!found;y++)for(int x=3;x<=7&&!found;x++){point=new Vector2(Screen.width*x*.1f,Screen.height*y*.1f);if(!DSPTouchControls.SetTarget(point))continue;yield return Wait(.10f);var list=a.activeTool.buildPreviews;found=list.Count>0;foreach(var p in list)found&=p.condition==EBuildCondition.Ok;}CheckTrue(found,"No original valid placement candidate");}
 static IEnumerator Movement(){report.phase="touch_movement";Write();var p=GameMain.mainPlayer;Vector3 before=p.position;Vector2 l=DSPTouchControls.MoveRect.center,r=DSPTouchControls.LookRect.center;float yaw=GameCamera.instance.rtsPoser.yawWanted;Note("HUD included in original UI camera",DSPTouchControls.RenderLayersValid(),DSPTouchControls.RenderEvidence());
  DSPTouchControls.Contact(801,TouchPhase.Began,l);DSPTouchControls.Contact(802,TouchPhase.Began,r);for(int i=1;i<=75;i++){DSPTouchControls.Contact(801,TouchPhase.Moved,l+new Vector2(Screen.width*.045f,Screen.height*.08f));DSPTouchControls.Contact(802,TouchPhase.Moved,r+new Vector2(i*1.5f,0));yield return Wait(.025f);}
  DSPTouchControls.Contact(801,TouchPhase.Ended,l);DSPTouchControls.Contact(802,TouchPhase.Ended,r);yield return Wait();
  Note("simultaneous move and look",Vector3.Distance(before,p.position)>2&&Mathf.Abs(Mathf.DeltaAngle(yaw,GameCamera.instance.rtsPoser.yawWanted))>2,"distance="+Vector3.Distance(before,p.position)+" yaw="+yaw+" -> "+GameCamera.instance.rtsPoser.yawWanted);
  Note("release clears movement and look",DSPTouchControls.Move==Vector2.zero&&!DSPTouchControls.Looking,"no retained finger owners");
  int taps=DSPPadInput.WorldTapPresses;DSPTouchControls.Contact(803,TouchPhase.Began,r);DSPTouchControls.Contact(803,TouchPhase.Ended,r);yield return Wait();Note("look tap never clicks world",DSPPadInput.WorldTapPresses==taps,"world taps="+taps+" -> "+DSPPadInput.WorldTapPresses);
  float zoom=GameCamera.instance.rtsPoser.distCoefWanted;yield return Button("zoomIn");float near=GameCamera.instance.rtsPoser.distCoefWanted;yield return Button("zoomOut");Note("camera zoom buttons",near<zoom&&GameCamera.instance.rtsPoser.distCoefWanted>near,"distance="+zoom+" -> "+near+" -> "+GameCamera.instance.rtsPoser.distCoefWanted);
 }
 static IEnumerator Building(){report.phase="touch_building";Write();yield return Select(2301);DSPTouchControls.SetTarget(new Vector2(Screen.width*.5f,Screen.height*.58f));yield return Wait();float yaw=GameMain.mainPlayer.controller.actionBuild.clickTool.yaw;
  CheckTrue(DSPTouchControls.ClickDiagnostic("rotate"),"rotation HUD unavailable");CheckTrue(DSPTouchControls.ClickDiagnostic("rotate"),"rotation HUD unavailable");CheckTrue(DSPTouchControls.ClickDiagnostic("rotate"),"rotation HUD unavailable");yield return Wait(1);float after=GameMain.mainPlayer.controller.actionBuild.clickTool.yaw;Note("three rapid rotation buttons",Mathf.Abs(Mathf.Repeat(after-yaw,360)-270)<.1f,"yaw="+yaw+" -> "+after);
  yield return Button("fine");yaw=after;yield return Button("rotate");after=GameMain.mainPlayer.controller.actionBuild.clickTool.yaw;Note("miner original fine rotation",Mathf.Abs(Mathf.DeltaAngle(yaw,after))>.1f&&Mathf.Abs(Mathf.DeltaAngle(yaw,after))<90,"yaw="+yaw+" -> "+after);
  Vector2 before=DSPTouchControls.Pointer;yield return Button("nright");Note("fine pointer nudge",Vector2.Distance(before,DSPTouchControls.Pointer)>.1f,"pointer="+before+" -> "+DSPTouchControls.Pointer);yield return Button("cancel");Note("cancel releases modifier",!DSPTouchControls.Fine&&!DSPPadInput.GetKey(KeyCode.LeftShift),"fine cleared");
  yield return Select(2201);yield return FindClick();int count=Count(2201);Vector2 p=DSPTouchControls.Pointer;DSPTouchControls.Contact(810,TouchPhase.Began,p);DSPTouchControls.Contact(810,TouchPhase.Moved,p+Vector2.right*4);DSPTouchControls.Contact(810,TouchPhase.Ended,p+Vector2.right*4);yield return Wait(.5f);Note("preview drag does not place",Count(2201)==count,"count="+count+" -> "+Count(2201));yield return FindClick();yield return DSPPadRenderDiagnostics.Capture("touch-building-preview");yield return Button("confirm");yield return Wait(2);Note("original building placement",Count(2201)==count+1,"before="+count+" after="+Count(2201));yield return Button("cancel");
 }
 static IEnumerator Belts(){report.phase="touch_belts";Write();yield return Select(2001);var p=GameMain.mainPlayer;var a=p.controller.actionBuild;yield return FindClick();Vector2 start=DSPTouchControls.Pointer;
  yield return Button("up");int height=a.pathTool.altitude;yield return Button("down");Note("belt height controls",height>0&&a.pathTool.altitude==0,"up="+height+" down="+a.pathTool.altitude);
  yield return Button("confirm");Note("belt start stage",p.controller.cmd.stage>0,"stage="+p.controller.cmd.stage);CheckTrue(p.controller.cmd.stage>0,"Belt start failed");int count=Count(2001);bool found=false;
  foreach(var d in new[]{new Vector2(140,0),new Vector2(-140,0),new Vector2(0,120),new Vector2(0,-120),new Vector2(220,90)}){if(!DSPTouchControls.SetTarget(start+d*Screen.width/1280))continue;yield return Wait(.25f);found=a.pathTool.buildPreviews.Count>=3;foreach(var b in a.pathTool.buildPreviews)found&=b.condition==EBuildCondition.Ok;if(found)break;}
  CheckTrue(found,"No valid multi-segment belt preview");yield return DSPPadRenderDiagnostics.Capture("touch-belt-preview");int previews=a.pathTool.buildPreviews.Count;yield return Button("rotate");yield return Button("rotate");yield return Wait();int afterDrag=Count(2001);Note("belt endpoint edit does not place",afterDrag==count,"count="+count+" -> "+afterDrag);
  // Return to a verified candidate after cycling original alternatives.
  bool valid=true;foreach(var b in a.pathTool.buildPreviews)valid&=b.condition==EBuildCondition.Ok;if(!valid){yield return Button("rotate");}
  yield return Button("confirm");yield return Wait(2);Note("original belt segment placement",Count(2001)>count,"before="+count+" after="+Count(2001)+" preview="+previews);
  yield return Button("cancel");yield return Button("cancel");
 }
 static int Box(Vector3 pos,Quaternion rot){var f=GameMain.localPlanet.factory;var item=LDB.items.Select(2101);var pre=new PrebuildData{protoId=2101,modelIndex=(short)item.ModelIndex,pos=pos,rot=rot,pos2=pos,rot2=rot,itemRequired=0};int id=f.AddPrebuildDataWithComponents(pre);f.BuildFinally(GameMain.mainPlayer,id);for(int i=1;i<f.entityCursor;i++)if(f.entityPool[i].id==i&&f.entityPool[i].protoId==2101&&(f.entityPool[i].pos-pos).sqrMagnitude<.01f)return i;throw new Exception("Fixture box creation failed");}
 static IEnumerator Inserters(){report.phase="touch_inserters";Write();var p=GameMain.mainPlayer;var planet=GameMain.localPlanet;var a=p.controller.actionBuild;
  // Original build APIs provide two test containers only. The sorter itself must be made through touch confirmation.
  Vector3 up=p.position.normalized,right=Vector3.ProjectOnPlane(Camera.main.transform.right,up).normalized,forward=Vector3.Cross(right,up).normalized;
  Vector3 pa=planet.aux.Snap((p.position+forward*8-right*2).normalized*planet.realRadius,true);Vector3 gridRight=Maths.SphericalRotation(pa,0)*Vector3.right;Vector3 pb=planet.aux.Snap((pa+gridRight*4).normalized*planet.realRadius,true);pa=pa.normalized*(planet.data.QueryHeight(pa)+.05f);pb=pb.normalized*(planet.data.QueryHeight(pb)+.05f);
  int from=Box(pa,Maths.SphericalRotation(pa,0)),to=Box(pb,Maths.SphericalRotation(pb,0));Note("sorter fixture containers",from>0&&to>0,"Test-only original factory API boxes, not touch placement; from="+pa+" to="+pb+" distance="+Vector3.Distance(pa,pb));yield return Select(2011);
  Vector2 start=Camera.main.WorldToScreenPoint(pa),end=Camera.main.WorldToScreenPoint(pb);CheckTrue(DSPTouchControls.SetTarget(start),"Fixture start blocked by UI");yield return Wait(.5f);yield return Button("confirm");Note("sorter selects source",a.inserterTool.startObjectId==from&&p.controller.cmd.stage==1,"source="+a.inserterTool.startObjectId+" expected="+from);CheckTrue(p.controller.cmd.stage==1,"Sorter source not selected");
  CheckTrue(DSPTouchControls.SetTarget(end),"Fixture end blocked by UI");yield return Wait(.5f);int before=Count(2011);int candidates=0;bool valid=false;string conditions="";
  for(int i=0;i<20;i++){var list=a.inserterTool.buildPreviews;valid=list.Count>0;foreach(var b in list){valid&=b.condition==EBuildCondition.Ok;conditions+=b.condition+" ";}if(valid){candidates=list.Count;break;}yield return Button("rotate");}
  Note("sorter valid target preview",valid,"previews="+candidates+" start="+from+" end="+to+" conditions="+conditions);CheckTrue(valid,"No original valid sorter connection");yield return DSPPadRenderDiagnostics.Capture("touch-sorter-preview");Note("sorter preview does not place",Count(2011)==before,"count="+before);
  yield return Button("confirm");yield return Wait(3);Note("original sorter placement",Count(2011)==before+1,"before="+before+" after="+Count(2011));yield return Button("cancel");
 }
 static IEnumerator Cleanup(){DSPTouchControls.Reset();if(GameMain.mainPlayer!=null){GameMain.mainPlayer.SetHandItems(0,0);GameMain.mainPlayer.controller.actionBuild.Close();}yield return Wait(.3f);}
 static IEnumerator Guard(string stage,IEnumerator run){report.phase=stage;Write();var stack=new Stack<IEnumerator>();stack.Push(run);while(stack.Count>0){bool more=false;object next=null;Exception error=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception e){error=e;}if(error!=null){report.errors.Add(stage+": "+error);Write();yield return DSPPadRenderDiagnostics.Capture("touch-failure-"+stage);break;}if(!more){(stack.Pop() as IDisposable)?.Dispose();continue;}if(next is IEnumerator){stack.Push((IEnumerator)next);continue;}yield return next;}while(stack.Count>0)(stack.Pop() as IDisposable)?.Dispose();yield return Cleanup();}
 public static IEnumerator Run(){if(!DSPPadDiagnosticLaunch.AutomaticActionsAllowed||!DSPTouchControls.Enabled)yield break;report=new Report{batchIdentifier=DSPPadDiagnosticLaunch.BatchIdentifier,buildVersion=DSPPadDiagnosticLaunch.BuildVersion,phase="begin"};Write();DSPTouchControls.DiagnosticMode(true);DSPPadBatchFixture.Prepare();yield return Wait(1);
  yield return Guard("movement",Movement());yield return Guard("building",Building());yield return Guard("belts",Belts());yield return Guard("inserters",Inserters());
  UIRoot.instance.uiGame.OpenTechTree();yield return Wait(.5f);DSPTouchControls.Contact(890,TouchPhase.Began,DSPTouchControls.MoveRect.center);DSPTouchControls.Contact(890,TouchPhase.Moved,DSPTouchControls.MoveRect.center+Vector2.up*80);yield return Wait();Note("fullscreen blocks movement",DSPTouchControls.Move==Vector2.zero,"technology active="+UIRoot.instance.uiGame.techTree.active);UIRoot.instance.uiGame.ShutTechTree();yield return Wait();
  string save="Touch-Regression-"+DSPPadDiagnosticLaunch.BuildVersion;long savedTick=GameMain.gameTick;int[] protos={2201,2001,2011};int[] counts={Count(2201),Count(2001),Count(2011)};bool saved=GameSave.SaveCurrentGame(save);Note("save touch-built world",saved,save);if(saved){DSPGame.EndGame();yield return Wait(2);DSPGame.StartGame(save);yield return Wait(2);float deadline=Time.realtimeSinceStartup+180;while((!GameMain.isRunning||GameMain.isLoading||GameMain.localPlanet==null||!GameMain.localPlanet.factoryLoaded||GameMain.gameTick<savedTick)&&Time.realtimeSinceStartup<deadline)yield return Wait(1);bool loaded=GameMain.isRunning&&!GameMain.isLoading&&GameMain.localPlanet!=null&&GameMain.localPlanet.factoryLoaded&&GameMain.gameTick>=savedTick;string evidence="saved tick="+savedTick+" loaded tick="+GameMain.gameTick;if(loaded)for(int i=0;i<protos.Length;i++){int n=Count(protos[i]);loaded&=n==counts[i];evidence+=" proto="+protos[i]+":"+counts[i]+"->"+n;}Note("reload touch-built world",loaded,evidence);}

  yield return Wait(2);yield return DSPPadRenderDiagnostics.Capture("touch-overview");DSPTouchControls.DiagnosticMode(false);Passed=report.errors.Count==0;foreach(var c in report.checks)Passed&=c.passed;report.completed=true;report.phase=Passed?"passed":"failed";Write();
 }
}
